base<-ds$variables;ix<-match(base$SEQN,d$SEQN);base$D1_included<-!is.na(ix);for(v in c('alcohol4','log10_cotinine','CRP_mgL','log_CRP','education','pir','diabetes','hypertension','any_nsaid','any_corticosteroid','any_statin','race_eth','sex','smoking')){base[[v]]<-d[[v]][ix]};base$cycle_factor<-factor(base$SDDSRVYR)
ev<-c('log10_cotinine','alcohol4','education','pir','diabetes','hypertension','any_nsaid','any_corticosteroid','any_statin');base$D1_complete<-base$D1_included&complete.cases(base[,ev]);ds$variables<-base;des<-subset(ds,D1_complete);full<-subset(ds,D1_included)
covars<-'log_Neutrophil + log_Lymphocyte + log_Platelet + age + sex + bmi + smoking + cycle_factor + race_eth';cells<-c('log_Neutrophil','log_Lymphocyte','log_Platelet');fits<-list();registry<-cf<-ct<-data.frame()
fit<-function(id,domain,extra='',outcome='depression',pois=FALSE){f<-as.formula(paste(outcome,'~',covars,extra));ww<-character();neutro_cat('\nMODEL_START',id,'\n');print(f);m<-withCallingHandlers(svyglm(f,design=domain,family=if(pois)quasipoisson(link='log')else quasibinomial()),warning=function(w){ww<<-c(ww,conditionMessage(w));neutro_cat('WARNING',conditionMessage(w),'\n');invokeRestart('muffleWarning')});print(summary(m));ci<-confint(m);cs<-coef(summary(m));b<-coef(m)[cells];cf<<-rbind(cf,data.frame(model=id,N=nobs(m),term=cells,beta=unname(b),SE=unname(sqrt(diag(vcov(m)))[cells]),effect=unname(exp(b)),lower=unname(exp(ci[cells,1])),upper=unname(exp(ci[cells,2])),P=unname(cs[cells,ncol(cs)])))
 for(j in 2:3){v<-setNames(rep(0,length(coef(m))),names(coef(m)));v[cells[1]]<-1;v[cells[j]]<--1;c<-svycontrast(m,v);bb<-as.numeric(coef(c));se<-as.numeric(SE(c));r<-data.frame(model=id,contrast=paste(cells[1],cells[j],sep=' - '),beta=bb,SE=se,df=degf(domain),P=2*pt(-abs(bb/se),degf(domain)));ct<<-rbind(ct,r);print(r)}
 registry<<-rbind(registry,data.frame(model=id,N=nobs(m),formula=paste(deparse(f),collapse=' '),family=family(m)$family,design_df=degf(domain),residual_df=m$df.residual,converged=m$converged,warning_count=length(ww),warnings=paste(ww,collapse=' | ')));fits[[id]]<<-m;neutro_cat('MODEL_END',id,'\n')}
extra<-c('','+ log10_cotinine','+ log10_cotinine + alcohol4','+ log10_cotinine + alcohol4 + education + pir','+ log10_cotinine + alcohol4 + education + pir + diabetes + hypertension','+ log10_cotinine + alcohol4 + education + pir + diabetes + hypertension + any_nsaid + any_corticosteroid + any_statin');for(i in 0:5)fit(paste0('L',i),des,extra[i+1]);beta<-sapply(fits,function(m)coef(m)['log_Neutrophil']);csv(data.frame(model=names(fits),N=nrow(des$variables),beta=unname(beta),percent_change=100*(beta-beta[1])/beta[1]),'D1_2_layer_changes.csv')
lsd<-sqrt(as.numeric(coef(svyvar(~log_Neutrophil,des))));qq<-as.numeric(coef(svyquantile(~Neutrophil_count,des,quantiles=c(.25,.75),ci=FALSE)));sc<-data.frame();for(id in c('L0','L1','L3','L5')){m<-fits[[id]];b<-coef(m)['log_Neutrophil'];ci<-confint(m)['log_Neutrophil',];delta<-c(lsd,log(qq[2]/qq[1]));sc<-rbind(sc,data.frame(model=id,scale=c('per_weighted_SD','Q25_to_Q75'),OR=unname(exp(b*delta)),lower=unname(exp(ci[1]*delta)),upper=unname(exp(ci[2]*delta))))};csv(sc,'D1_2_effect_scales.csv');csv(data.frame(N=nrow(des$variables),log_SD=lsd,Q25=qq[1],Q75=qq[2]),'D1_2_scale_parameters.csv')
vd<-svyvar(~log10_cotinine+log_Neutrophil,des);vv<-as.matrix(vd);qqc<-as.numeric(coef(svyquantile(~log10_cotinine,des,quantiles=c(.05,.25,.5,.75,.95),ci=FALSE)));csv(data.frame(N=nrow(des$variables),mean=as.numeric(coef(svymean(~log10_cotinine,des))),SD=sqrt(vv[1,1]),Q05=qqc[1],Q25=qqc[2],Q50=qqc[3],Q75=qqc[4],Q95=qqc[5],weighted_correlation=vv[1,2]/sqrt(vv[1,1]*vv[2,2])),'D1_2_cotinine_description.csv')
