adult<-subset(full,age>=20);csv(data.frame(N=nrow(adult$variables),depression_cases=sum(adult$variables$depression==1)),'D1_4_adult_counts.csv');fit('adult_M3',adult);fit('adult_PHQtotal_M3',adult,outcome='PHQ9_total',pois=TRUE)
