pop<-subset(ds,age>=18&WTMEC2YR>0);groups<-list(included=subset(pop,D1_included),excluded=subset(pop,!D1_included));comparison<-data.frame();stats<-lapply(groups,function(g){c(mean=as.numeric(coef(svymean(~age,g))),variance=as.numeric(coef(svyvar(~age,g))))});smd_age<-(stats$included[1]-stats$excluded[1])/sqrt((stats$included[2]+stats$excluded[2])/2)
comparison<-rbind(comparison,data.frame(variable='age',level='mean',N_in=nrow(groups$included$variables),N_out=nrow(groups$excluded$variables),unweighted_in=mean(groups$included$variables$age),unweighted_out=mean(groups$excluded$variables$age),weighted_in=stats$included[1],weighted_out=stats$excluded[1],SMD=unname(smd_age)))
for(v in c('RIAGENDR','RIDRETH1','DMDEDUC2','INDFMPIR','SDDSRVYR')){
 if(v=='INDFMPIR'){s<-lapply(groups,function(g){g<-subset(g,!is.na(INDFMPIR));c(mean=as.numeric(coef(svymean(~INDFMPIR,g))),variance=as.numeric(coef(svyvar(~INDFMPIR,g))))});comparison<-rbind(comparison,data.frame(variable=v,level='mean_nonmissing',N_in=sum(!is.na(groups$included$variables[[v]])),N_out=sum(!is.na(groups$excluded$variables[[v]])),unweighted_in=mean(groups$included$variables[[v]],na.rm=TRUE),unweighted_out=mean(groups$excluded$variables[[v]],na.rm=TRUE),weighted_in=s$included[1],weighted_out=s$excluded[1],SMD=unname((s$included[1]-s$excluded[1])/sqrt((s$included[2]+s$excluded[2])/2))));levels<-'Missing'}else levels<-c(sort(unique(as.character(pop$variables[[v]][!is.na(pop$variables[[v]])]))),'Missing')
 for(l in levels){res<-lapply(groups,function(g){flag<-if(l=='Missing')is.na(g$variables[[v]])else !is.na(g$variables[[v]])&as.character(g$variables[[v]])==l;gg<-update(g,flag=as.numeric(flag));c(N=sum(flag),unweighted=mean(flag),weighted=as.numeric(coef(svymean(~flag,gg))))});p1<-res$included[3];p0<-res$excluded[3];den<-sqrt((p1*(1-p1)+p0*(1-p0))/2);comparison<-rbind(comparison,data.frame(variable=v,level=l,N_in=res$included[1],N_out=res$excluded[1],unweighted_in=100*res$included[2],unweighted_out=100*res$excluded[2],weighted_in=100*p1,weighted_out=100*p0,SMD=if(den>0)unname((p1-p0)/den)else 0))}
};csv(comparison,'D1_5_included_excluded_comparison.csv');csv(data.frame(group=c('total','included','excluded'),N=c(nrow(pop$variables),nrow(groups$included$variables),nrow(groups$excluded$variables))),'D1_5_population_counts.csv')
